"""Resource episode controls; samples are injected, never generated by load."""
import json
from pathlib import Path
import tempfile
import unittest
from unittest import mock

from chrono_state import notifications as n
from chrono_state import resource_watch as r
from host_admission import parse_pressure_level


class ResourceEpisodes(unittest.TestCase):
    def setUp(self):
        self.temp = tempfile.TemporaryDirectory(prefix='notice-resource-', dir='/tmp')
        self.addCleanup(self.temp.cleanup)
        self.root = Path(self.temp.name)
        self.store = n.NotificationStore(self.root)
        self.store.initialize('2000-01-01T00:00:00+00:00')
        self.config = r.ResourceConfig()

    def sample(self, disk=100, memory='normal'):
        return r.publish_sample(self.store, {
            'disk_free_bytes': None if disk is None else disk * r.GIB,
            'memory_pressure': memory, 'disk_path': '/fixture/Data'}, self.config)

    def levels(self, resource):
        return [x['metadata']['level'] for x in self.store.list_pending()
                if x['identity'][1] == resource]

    def test_disk_episode_dedup_escalation_hysteresis_recovery_and_new_episode(self):
        self.sample()
        self.assertEqual(self.store.list_pending(), [])
        self.sample(24)
        self.sample(24)
        self.sample(14)
        self.sample(16)  # Critical holds until >=17 GiB.
        self.sample(17)
        self.sample(17)
        self.sample(26)  # Warn holds until >=27 GiB.
        self.sample(26)
        self.assertCountEqual(self.levels('disk'), ['warn', 'critical', 'warn'])
        self.sample(27)
        self.assertNotIn('recovered', self.levels('disk'))
        self.sample(27)
        self.sample(90)
        self.assertCountEqual(self.levels('disk'), ['warn', 'critical', 'warn', 'recovered'])
        old_ids = {x['id'] for x in self.store.list_pending()}
        self.sample(24)
        self.assertEqual(len(set(x['id'] for x in self.store.list_pending()) - old_ids), 1)

    def test_memory_enum_not_free_percentage_and_consecutive_recovery(self):
        self.assertEqual([parse_pressure_level(str(v)) for v in (1, 2, 4, 0, 3)],
                         ['normal', 'warn', 'critical', 'unknown', 'unknown'])
        self.sample(memory='warn')
        self.sample(memory='warn')
        self.sample(memory='critical')
        self.sample(memory='normal')
        self.sample(memory='critical')  # A bad sample resets the recovery count.
        self.sample(memory='normal')
        self.assertCountEqual(self.levels('memory'), ['warn', 'critical'])
        self.sample(memory='normal')
        self.assertCountEqual(self.levels('memory'), ['warn', 'critical', 'recovered'])

    def test_reescalation_after_ack_has_new_identity_in_same_episode(self):
        first = self.sample(10, 'critical')
        self.assertEqual(len(first), 2)  # Initial escalation is the positive control.
        self.store.acknowledge([notice['id'] for notice in first])
        self.assertEqual(self.sample(10, 'critical'), [])
        self.sample(20, 'warn')
        down = self.sample(20, 'warn')
        self.assertEqual(len(down), 2)
        self.store = n.NotificationStore(self.root)  # Persist sequence across restart.
        again = self.sample(10, 'critical')
        self.assertEqual(len(again), 2)
        self.assertTrue(all(notice['state'] == 'pending' for notice in again))
        self.assertTrue({x['id'] for x in first}.isdisjoint(x['id'] for x in again))
        self.assertEqual([x['metadata']['episode'] for x in first],
                         [x['metadata']['episode'] for x in again])
        self.assertEqual(self.sample(10, 'critical'), [])

    def test_unknown_is_notice_not_normal_and_recovery_is_debounced(self):
        self.sample(None, 'unknown')
        self.sample(None, 'unknown')
        self.assertEqual(len(self.store.list_pending()), 2)
        self.assertEqual(self.levels('disk'), ['unknown'])
        self.assertEqual(self.levels('memory'), ['unknown'])
        self.sample()
        self.assertEqual(len(self.store.list_pending()), 2)
        self.sample()
        self.assertEqual(len(self.store.list_pending()), 4)

    def test_failed_commit_does_not_burn_episode(self):
        before = self.store.path.read_bytes()
        with mock.patch.object(self.store, '_write', side_effect=OSError('disk full')):
            with self.assertRaises(OSError):
                self.sample(14, 'critical')
        self.assertEqual(self.store.path.read_bytes(), before)
        self.sample(14, 'critical')
        self.assertEqual(len(self.store.list_pending()), 2)

    def test_unknown_does_not_erase_disk_hysteresis(self):
        self.sample(24)
        self.sample(None)
        self.sample(26)
        self.sample(26)
        self.assertNotIn('recovered', self.levels('disk'))
        self.sample(27)
        self.sample(27)
        self.assertIn('recovered', self.levels('disk'))

    def test_restart_and_multiple_samplers_share_durable_episode_ids(self):
        self.sample(14, 'critical')
        ids = {x['id'] for x in self.store.list_pending()}
        self.store = n.NotificationStore(self.root)
        self.sample(14, 'critical')
        self.store.acknowledge(ids)
        self.sample(14, 'critical')
        self.assertEqual(self.store.list_pending(), [])
        self.sample()
        self.sample()
        self.sample(14, 'critical')
        self.assertEqual(len(self.store.list_pending()), 4)

    def test_exact_boundaries_invalid_values_and_configuration(self):
        self.assertEqual(r.disk_level(25 * r.GIB, 'normal', self.config), 'normal')
        self.assertEqual(r.disk_level(15 * r.GIB, 'normal', self.config), 'warn')
        for value in (None, -1, float('nan'), float('inf'), '12', True):
            self.assertEqual(r.disk_level(value, 'normal', self.config), 'unknown')
        for args in ({'critical_gib': 25}, {'warn_gib': float('nan')},
                     {'recovery_samples': 0}, {'hysteresis_gib': 0}, {'period': 0}):
            with self.assertRaises(ValueError):
                r.ResourceConfig(**args)
        with mock.patch.dict('os.environ', {'CHRONO_NOTIFICATION_RECOVERY_SAMPLES': '1.5'}):
            with self.assertRaises(ValueError):
                r.ResourceConfig.from_env()

    def test_darwin_measures_data_volume_and_missing_telemetry_is_unknown(self):
        with mock.patch.object(r.sys, 'platform', 'darwin'), \
                mock.patch.object(r.shutil, 'disk_usage', return_value=mock.Mock(free=123)) as disk, \
                mock.patch.object(r, 'read_pressure_level', return_value='critical'):
            sample = r.sample_resources(self.root)
        disk.assert_called_once_with(Path('/System/Volumes/Data'))
        self.assertEqual(sample['disk_free_bytes'], 123)
        self.assertEqual(sample['memory_pressure'], 'critical')
        with mock.patch.object(r.sys, 'platform', 'darwin'), \
                mock.patch.object(r.shutil, 'disk_usage', side_effect=OSError('unavailable')), \
                mock.patch.object(r, 'read_pressure_level', return_value='unknown'):
            failed = r.sample_resources(self.root)
        self.assertIsNone(failed['disk_free_bytes'])
        self.assertEqual(failed['memory_pressure'], 'unknown')
        self.assertEqual(set(failed['errors']), {'disk', 'memory'})

    def test_disabled_sampler_creates_nothing(self):
        before = list(self.root.rglob('*'))
        with mock.patch.object(r, 'run_sampler') as run:
            self.assertEqual(r.main(['--vault', str(self.root), '--session', 'none', '--token', 'none']), 0)
        run.assert_not_called()
        self.assertEqual(list(self.root.rglob('*')), before)


if __name__ == '__main__':
    unittest.main()
